static lstr L897 = {0, 510, "// std/internal/terminal. Whether a stream is a terminal, and its width in columns.\012#include <sys/ioctl.h>\012#include <unistd.h>\012\012static bool narra_terminal_is_terminal(int64_t descriptor) {\012  return isatty((int)descriptor) != 0;\012}\012\012// The columns of the terminal on the descriptor; 0 when it is not a terminal or reports no width.\012static int64_t narra_terminal_columns(int64_t descriptor) {\012  struct winsize size;\012  if (ioctl((int)descriptor, TIOCGWINSZ, &size) != 0) return 0;\012  return (int64_t)size.ws_col;\012}\012"};
