static lstr L3159 = {0, 651, "\012// Closure environments. A count of 0 marks an environment on the caller's\012// stack, which is never counted or freed.\012typedef struct narra_env {\012  int64_t rc;\012  void (*drop)(struct narra_env*);\012  void (*share)(struct narra_env*);\012} narra_env;\012static void narra_env_retain(narra_env* e) {\012  if (e) NARRA_RC_RETAIN(e->rc);\012}\012static void narra_env_release(narra_env* e) {\012  if (e && NARRA_RC_RELEASE(e->rc)) {\012    e->drop(e);\012    narra_free(e);\012  }\012}\012static void narra_env_share_parts(void* p) {\012  narra_env* e = p;\012  e->share(e);\012}\012static void narra_env_share(narra_env* e) {\012  if (e && narra_rc_share(&e->rc)) narra_share(e, narra_env_share_parts);\012}\012"};
