static lstr L10261 = {0, 898, "// std/template: the parts type and the tag of tagged templates (SPEC.md section 2, D114).\012//\012// A tag whose first parameter is Raw gets the source text of each part, with\012// no escape decoded; a tag whose first parameter is Array<string> gets the\012// parts with their escapes decoded.\012\012import * as Arrays from \"std/array\"\012import * as Ranges from \"std/range\"\012import * as Str from \"std/string\"\012\012export distinct type Raw = Array<string>\012\012// TypeScript's String.raw: the parts as written, with the values between them.\012@const\012export function raw(parts: Raw, values: Array<string>): string uses alloc {\012  const texts = Raw.toArray(parts)\012  let builder = Str.builder()\012  for (const index of Ranges.upTo(Arrays.length(texts))) {\012    Str.append(mutable builder, texts[index])\012    if (index < Arrays.length(values)) {\012      Str.append(mutable builder, values[index])\012    }\012  }\012  return Str.build(builder)\012}\012"};
